PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <https://example.com/ref#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?zone ?point ?series ?name WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
  FILTER(contains(?lbl, "Perimeter_top_ZN_1"))
  OPTIONAL { ?point brick:hasProperty ?z . ?point ref:hasTimeseriesId ?series }
  OPTIONAL { ?point rdfs:label ?name }
}

